// parallel_macros.rs - Multi-threaded processing with 40 threads
// Generated by step4_bootstrap - Parallel Processing

use rayon::prelude::*;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

#[macro_export]
macro_rules! parallel_foreach {
    ($repo_var:ident, $repos_expr:expr, $action:expr) => {{
        use rayon::prelude::*;
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::sync::Arc;
        
        // Configure rayon to use 40 threads
        rayon::ThreadPoolBuilder::new()
            .num_threads(40)
            .build_global()
            .unwrap_or(());
        
        let repos = $repos_expr;
        let total_repos = repos.len();
        let processed = Arc::new(AtomicUsize::new(0));
        let total_modules = Arc::new(AtomicUsize::new(0));
        
        println!("🚀 Starting parallel processing with 40 threads...");
        println!("📊 Processing {} repositories", total_repos);
        
        let results: Vec<_> = repos
            .into_par_iter()
            .map(|$repo_var| {
                let count = processed.fetch_add(1, Ordering::Relaxed) + 1;
                
                if count % 50 == 0 {
                    let modules_so_far = total_modules.load(Ordering::Relaxed);
                    println!("⚡ Thread progress: {}/{} repos, {} modules", 
                             count, total_repos, modules_so_far);
                }
                
                let result = $action;
                
                // Update module count
                if let Ok(modules) = &result {
                    total_modules.fetch_add(modules.len(), Ordering::Relaxed);
                }
                
                result
            })
            .collect();
        
        let final_modules = total_modules.load(Ordering::Relaxed);
        println!("🎯 Parallel processing complete: {} repos, {} modules", 
                 results.len(), final_modules);
        
        results
    }};
}

#[macro_export]
macro_rules! parallel_git_processing {
    () => {{
        parallel_foreach!(gitrepo, git_subs!(), {
            let git_sub_result = git_sub!(&gitrepo);
            let extracted_mods = extractmods!(git_sub_result);
            Ok(mkmods!(extracted_mods))
        })
    }};
}
